sys_script_include.script:
var AllocateNowUtils = Class.create();
AllocateNowUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkManagerAlreadyUsed: function() {
        var managerId = this.getParameter('sysparm_manager_id');
        var currentBaseId = this.getParameter('sysparm_base_id');

        if (!managerId) {
            return 'false';
        }

		var bond = new GlideRecord('x_1523510_alloca_0_bonds');
        bond.addQuery('user', managerId);
        bond.addQuery('function.name', 'Base Manager');

        if (currentBaseId) {
            bond.addQuery('base', '!=', currentBaseId);
        }

        bond.query();

        if (bond.next()) {
            return 'true';
        }

        return 'false';
    },

	isDuplicateBase: function() {
    var fieldName = this.getParameter('sysparm_field_name');
    var fieldValue = this.getParameter('sysparm_field_value');
    var currentBase = this.getParameter('sysparm_current_base');

    if (!fieldName || !fieldValue) {
        return 'false';
    }

    var base = new GlideRecord('x_1523510_alloca_0_bases');
    base.addQuery(fieldName, fieldValue);

    if (currentBase) {
        base.addQuery('sys_id', '!=', currentBase);
    }
    base.query();
    return base.hasNext() ? 'true' : 'false';
},

	isDuplicateCityState: function() {
		var city = this.getParameter('sysparm_city');
		var state = this.getParameter('sysparm_state');
		var currentBase = this.getParameter('sysparm_current_base');

		if (!city || !state) {
        return 'false';
    }

		var base = new GlideRecord('x_1523510_alloca_0_bases');
		base.addQuery('city', city);
		base.addQuery('state', state);

		if (currentBase) {
			base.addQuery('sys_id', '!=', currentBase);
    }

    base.query();

    return base.hasNext() ? 'true' : 'false';
},

    type: 'AllocateNowUtils'
});
